/**
 * Re-implementation of CPython's `int(str)` conversion.
 *
 * Values are returned as `BigInt` so that arbitrary precision is preserved
 * exactly like Python integers (e.g. `--a 123456789012345678901234567890`).
 */

import { decimalDigitValue, isDecimalDigit, pyStrip } from './unicode.mjs';

/** Raised when the text is not a valid integer literal, mirroring `ValueError`. */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

/**
 * Convert a string to an integer following Python's base-10 rules:
 *   - surrounding Unicode whitespace is stripped,
 *   - an optional ASCII `+`/`-` sign may follow,
 *   - Unicode decimal digits (category Nd) are accepted,
 *   - single underscores are allowed, but only between two digits.
 *
 * @param {string} text
 * @returns {bigint}
 */
export function pyInt(text) {
  const stripped = pyStrip(text);
  const chars = Array.from(stripped);

  let index = 0;
  let sign = '';
  if (chars[index] === '+' || chars[index] === '-') {
    sign = chars[index] === '-' ? '-' : '';
    index += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; index < chars.length; index += 1) {
    const char = chars[index];
    if (char === '_') {
      // An underscore needs a digit on both sides.
      if (!previousWasDigit) throw invalidLiteral(text);
      previousWasDigit = false;
      continue;
    }
    const value = decimalDigitValue(char);
    if (value < 0) throw invalidLiteral(text);
    digits += String(value);
    previousWasDigit = true;
  }

  if (digits.length === 0 || !previousWasDigit) throw invalidLiteral(text);
  return BigInt(sign + digits);
}

/** True when `pyInt` would succeed for `text`. */
export function isPyInt(text) {
  try {
    pyInt(text);
    return true;
  } catch {
    return false;
  }
}

export { isDecimalDigit };

function invalidLiteral(text) {
  return new PyValueError(
    `invalid literal for int() with base 10: ${JSON.stringify(text)}`,
  );
}

