/**
 * Python's `repr()` for string objects — needed verbatim because argparse
 * embeds it in its error messages (`invalid int value: 'abc'`).
 */

import { isPrintable } from './unicode.mjs';

/**
 * Render `text` the way CPython's `repr(str)` does: single quotes by default,
 * double quotes when the value contains a single quote but no double quote,
 * and `\x`/`\u`/`\U` escapes for non-printable characters.
 *
 * @param {string} text
 * @returns {string}
 */
export function pyRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;

  for (const char of text) {
    if (char === quote || char === '\\') {
      out += `\\${char}`;
    } else if (char === '\n') {
      out += '\\n';
    } else if (char === '\r') {
      out += '\\r';
    } else if (char === '\t') {
      out += '\\t';
    } else if (isPrintable(char)) {
      out += char;
    } else {
      out += escapeCodePoint(char.codePointAt(0));
    }
  }

  return out + quote;
}

function escapeCodePoint(codePoint) {
  if (codePoint <= 0xff) return `\\x${hex(codePoint, 2)}`;
  if (codePoint <= 0xffff) return `\\u${hex(codePoint, 4)}`;
  return `\\U${hex(codePoint, 8)}`;
}

function hex(codePoint, width) {
  return codePoint.toString(16).padStart(width, '0');
}

