/**
 * Minimal stand-ins for the Python builtins used by the source script:
 * `str()` conversion semantics and `print()` output behaviour.
 */

import { writeStdout } from './sys.mjs';

/**
 * Python's `str()` for the value kinds this program can produce.
 * Integers are carried as `BigInt`, which stringifies exactly like a Python
 * `int` (no `n` suffix, no exponent notation, arbitrary precision).
 */
export function pyStr(value) {
  if (typeof value === 'bigint') return value.toString();
  if (value === null) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (value === undefined) return 'None';
  return String(value);
}

/**
 * Python's `print()`: arguments joined by `sep`, terminated by `end`, written
 * to stdout.  Defaults match CPython (`sep=' '`, `end='\n'`).
 */
export function pyPrint(...values) {
  let sep = ' ';
  let end = '\n';
  let items = values;

  const last = values[values.length - 1];
  if (isOptions(last)) {
    items = values.slice(0, -1);
    if (last.sep !== undefined && last.sep !== null) sep = last.sep;
    if (last.end !== undefined && last.end !== null) end = last.end;
  }

  writeStdout(items.map(pyStr).join(sep) + end);
}

function isOptions(value) {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    ('sep' in value || 'end' in value)
  );
}

