/**
 * The slice of Python's `sys` / `shutil` surface that argparse depends on:
 * the script arguments, synchronous stream writes and process termination.
 */

import { writeSync } from 'node:fs';
import { basename } from 'node:path';

/**
 * Equivalent of Python's `sys.argv`: element 0 is the program itself, the rest
 * are the user supplied arguments.  Under Node, `process.argv[0]` is the node
 * binary and `process.argv[1]` is the script, so the script takes slot 0.
 */
export const argv = [process.argv[1] ?? '', ...process.argv.slice(2)];

/** `os.path.basename(sys.argv[0])` — argparse's default `prog`. */
export function defaultProg() {
  return basename(argv[0] || '');
}

/** Unbuffered write to stdout so ordering with stderr is preserved. */
export function writeStdout(text) {
  writeSync(1, text);
}

/** Unbuffered write to stderr. */
export function writeStderr(text) {
  writeSync(2, text);
}

/** `sys.exit(status)`. */
export function exit(status = 0) {
  process.exit(status);
}

/**
 * `shutil.get_terminal_size().columns`: the `COLUMNS` environment variable
 * wins, then the real terminal size, then the 80 column fallback.
 */
export function terminalColumns() {
  const fromEnv = process.env.COLUMNS;
  if (fromEnv !== undefined && fromEnv !== '') {
    const parsed = Number.parseInt(fromEnv, 10);
    if (Number.isInteger(parsed) && parsed > 0) return parsed;
  }
  if (process.stdout.isTTY && process.stdout.columns > 0) {
    return process.stdout.columns;
  }
  return 80;
}

