/**
 * Exception types used by the argparse re-implementation.
 */

/** Raised by a `type` callable when it rejects a value (`ArgumentTypeError`). */
export class ArgumentTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentTypeError';
  }
}

/** An error tied to a specific action, rendered as `argument --a: <message>`. */
export class ArgumentError extends Error {
  constructor(action, message) {
    const name = action ? formatActionName(action) : null;
    super(name === null ? message : `argument ${name}: ${message}`);
    this.name = 'ArgumentError';
    this.action = action;
  }
}

/** Signals `parser.exit()` / `parser.error()`, carrying the process status. */
export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

function formatActionName(action) {
  if (action.optionStrings.length > 0) return action.optionStrings.join('/');
  if (action.metavar !== undefined && action.metavar !== null) return action.metavar;
  if (action.dest !== null) return action.dest;
  return null;
}

