/**
 * Collapse every run of whitespace into a single space and trim the ends,
 * matching argparse's `_whitespace_matcher` normalisation.
 */
export function collapseWhitespace(text) {
  return text.replace(/[\t\n\x0b\f\r ]+/g, ' ').trim();
}

/**
 * Greedily wrap `text` into lines of at most `width` characters.
 * Words longer than `width` are split, as `textwrap` does by default.
 *
 * @returns {string[]} the wrapped lines (empty array for blank input)
 */
export function wrapText(text, width) {
  const limit = Math.max(width, 1);
  const words = text.split(' ').filter((word) => word.length > 0);
  const lines = [];
  let current = '';

  for (const word of words) {
    let remaining = word;
    if (current.length > 0 && current.length + 1 + remaining.length <= limit) {
      current += ` ${remaining}`;
      continue;
    }
    if (current.length > 0) {
      lines.push(current);
      current = '';
    }
    while (remaining.length > limit) {
      lines.push(remaining.slice(0, limit));
      remaining = remaining.slice(limit);
    }
    current = remaining;
  }

  if (current.length > 0) lines.push(current);
  return lines;
}

