/**
 * Port of `schedule.Job`.
 *
 * A job records the interval and the time unit it was configured with.  The
 * unit properties (`.minutes`, `.seconds`, …) are chainable: they set the unit
 * and hand the same job back, which is why `schedule.every(n).minutes` yields a
 * job whose `interval` is still `n`.
 */

/** Cancel-job sentinel, equivalent to `schedule.CancelJob`. */
export const CancelJob = Object.freeze({ toString: () => 'CancelJob' });

export class Job {
  /**
   * @param {bigint|number} interval how many `unit`s between runs
   * @param {object|null} scheduler the scheduler the job will register with
   */
  constructor(interval, scheduler = null) {
    this.interval = interval;
    this.latest = null;
    this.jobFunc = null;
    this.unit = null;
    this.atTime = null;
    this.lastRun = null;
    this.nextRun = null;
    this.period = null;
    this.startDay = null;
    this.cancelAfter = null;
    this.tags = new Set();
    this.scheduler = scheduler;
  }

  get second() {
    assertSingularInterval(this, 'second');
    return this.seconds;
  }

  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minute() {
    assertSingularInterval(this, 'minute');
    return this.minutes;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  get hour() {
    assertSingularInterval(this, 'hour');
    return this.hours;
  }

  get hours() {
    this.unit = 'hours';
    return this;
  }

  get day() {
    assertSingularInterval(this, 'day');
    return this.days;
  }

  get days() {
    this.unit = 'days';
    return this;
  }

  get week() {
    assertSingularInterval(this, 'week');
    return this.weeks;
  }

  get weeks() {
    this.unit = 'weeks';
    return this;
  }

  /** `job.to(latest)` — schedule at a random interval in `[interval, latest]`. */
  to(latest) {
    this.latest = latest;
    return this;
  }

  /** `job.tag(...tags)`. */
  tag(...tags) {
    for (const value of tags) this.tags.add(value);
    return this;
  }
}

function assertSingularInterval(job, unitName) {
  // schedule asserts the singular unit properties are only used with interval 1.
  const interval = typeof job.interval === 'bigint' ? job.interval : BigInt(job.interval);
  if (interval !== 1n) {
    throw new Error(`Use ${unitName}s instead of ${unitName}`);
  }
}

