/**
 * Port of `schedule.Scheduler` — the job registry behind the module level
 * `schedule.every()` helper.
 */

import { Job } from './job.mjs';

export class Scheduler {
  constructor() {
    this.jobs = [];
  }

  /**
   * `scheduler.every(interval)` — build a job with the given interval.  The
   * value is stored untouched (no validation, no coercion), so
   * `every(0)`/`every(-3)` are accepted exactly as Python accepts them.
   *
   * @param {bigint|number} interval defaults to 1, like the Python signature
   * @returns {Job}
   */
  every(interval = 1n) {
    return new Job(interval, this);
  }

  /** `scheduler.clear(tag)`. */
  clear(tag = null) {
    this.jobs = tag === null ? [] : this.jobs.filter((job) => !job.tags.has(tag));
  }

  /** `scheduler.cancel_job(job)`. */
  cancelJob(job) {
    const index = this.jobs.indexOf(job);
    if (index !== -1) this.jobs.splice(index, 1);
  }
}

