/**
 * Unicode character classification helpers replicating the exact predicates
 * CPython relies on internally.
 *
 * Only Node.js built-in capabilities are used (Unicode property escapes in
 * regular expressions), no external module is involved.
 */

/**
 * The set of code points for which CPython's `Py_UNICODE_ISSPACE()` returns
 * true.  This is the whitespace definition used when `int()` strips its
 * argument, and it is *wider* than `/\s/` in JavaScript (it also contains the
 * C0 separators U+001C..U+001F and U+0085).
 */
const PY_SPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, // \t \n \v \f \r
  0x1c, 0x1d, 0x1e, 0x1f, // file/group/record/unit separators
  0x20, // space
  0x85, // next line
  0xa0, // no-break space
  0x1680, // ogham space mark
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, // line separator
  0x2029, // paragraph separator
  0x202f, // narrow no-break space
  0x205f, // medium mathematical space
  0x3000, // ideographic space
]);

const DECIMAL_DIGIT_RE = /^\p{Nd}$/u;

/** Non-printable per `str.isprintable()`: categories Cc, Cf, Cs, Co, Cn, Zl, Zp and Zs except U+0020. */
const NON_PRINTABLE_RE = /^[\p{C}\p{Zl}\p{Zp}\p{Zs}]$/u;

/** True when `codePoint` is whitespace in CPython's sense. */
export function isPySpace(codePoint) {
  return PY_SPACE.has(codePoint);
}

/** True when the character is a Unicode decimal digit (general category Nd). */
export function isDecimalDigit(char) {
  return DECIMAL_DIGIT_RE.test(char);
}

/**
 * Numeric value of a Unicode decimal digit.
 *
 * Every Nd run in the Unicode database is a whole decade laid out in ascending
 * order, so the value is the offset from the start of the maximal Nd run taken
 * modulo ten.  That also handles blocks such as the mathematical digits
 * (U+1D7CE..U+1D7FF) where five decades sit back to back.
 *
 * @returns {number} 0..9, or -1 when the character is not a decimal digit.
 */
export function decimalDigitValue(char) {
  if (!isDecimalDigit(char)) return -1;
  const codePoint = char.codePointAt(0);
  let runStart = codePoint;
  while (runStart > 0 && isDecimalDigit(String.fromCodePoint(runStart - 1))) {
    runStart -= 1;
  }
  return (codePoint - runStart) % 10;
}

/** True when the character is printable per `str.isprintable()`. */
export function isPrintable(char) {
  if (char === ' ') return true;
  return !NON_PRINTABLE_RE.test(char);
}

/** `str.strip()` restricted to CPython's whitespace set. */
export function pyStrip(text) {
  const chars = Array.from(text);
  let start = 0;
  let end = chars.length;
  while (start < end && isPySpace(chars[start].codePointAt(0))) start += 1;
  while (end > start && isPySpace(chars[end - 1].codePointAt(0))) end -= 1;
  return chars.slice(start, end).join('');
}

