/**
 * The full help text: usage, then one block per non-empty action group.
 *
 * @param {object[]} actions every action of the parser (for the usage line)
 * @param {{title: string, actions: object[]}[]} groups
 */
formatHelp(actions, groups) {
  const actionMaxLength = computeActionMaxLength(groups);
  let help = this.formatUsage(actions);

  for (const group of groups) {
    if (group.actions.length === 0) continue;
    help += `${group.title}:\n`;
    for (const action of group.actions) {
      help += this.formatAction(action, actionMaxLength);
    }
    help += '\n';
  }

  // argparse collapses runs of blank lines and normalises the trailing newline.
  help = help.replace(/\n\n\n+/g, '\n\n');
  return `${help.replace(/^\n+/, '').replace(/\n+$/, '')}\n`;
}

