/**
 * Port of argparse's `HelpFormatter`: usage line assembly, section headings,
 * invocation/help column alignment and wrapping — all reproduced so the output
 * is byte-for-byte identical to CPython's.
 */

import { terminalColumns } from '../python/sys.mjs';
import { collapseWhitespace, wrapText } from './textwrap.mjs';

const INDENT_INCREMENT = 2;
const MAX_HELP_POSITION = 24;

export class HelpFormatter {
  constructor(prog, { width = null } = {}) {
    this.prog = prog;
