/**
 * Port of `argparse.ArgumentParser` covering the behaviour the source script
 * can reach: long options with `store`/`help` actions, `--opt=value` syntax,
 * unambiguous prefix abbreviation, the negative-number heuristic, `--`
 * separation, required-argument checking and the exact error/usage wording.
 */

import { defaultProg, exit, writeStderr, writeStdout } from '../python/sys.mjs';
import { pyRepr } from '../python/repr.mjs';
import { HelpAction, StoreAction } from './actions.mjs';
import { ArgumentError, ArgumentTypeError, SystemExit } from './errors.mjs';
import { HelpFormatter } from './formatter.mjs';
import { argv as sysArgv } from '../python/sys.mjs';

/** argparse's `_negative_number_matcher` (Python's `\d` covers Unicode digits). */
const NEGATIVE_NUMBER = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

export class ArgumentParser {
  constructor({ prog = null, prefixChars = '-', addHelp = true } = {}) {
    this.prog = prog ?? defaultProg();
    this.prefixChars = prefixChars;
    this.actions = [];
    this.optionStringActions = new Map();
    this.groups = [
      { title: 'positional arguments', actions: [] },
      { title: 'options', actions: [] },
    ];

    if (addHelp) {
      this.addArgument('-h', '--help', {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * `parser.add_argument('--a', type=int, required=True)`.
   *
   * @param {...(string|object)} args option strings followed by an options object
   */
  addArgument(...args) {
    const optionStrings = args.filter((arg) => typeof arg === 'string');
    const options = args.find((arg) => typeof arg === 'object' && arg !== null) ?? {};

    if (optionStrings.length === 0) {
      throw new Error('positional arguments are not supported by this port');
    }

    const dest = options.dest ?? destFromOptionStrings(optionStrings, this.prefixChars);
    const kind = options.action ?? 'store';
    const spec = {
      optionStrings,
      dest,
      type: options.type ?? null,
      required: options.required ?? false,
      help: options.help ?? null,
      metavar: options.metavar ?? null,
      defaultValue: 'default' in options ? options.default : null,
    };

    const action = kind === 'help' ? new HelpAction(spec) : new StoreAction(spec);
    this.actions.push(action);
    this.groups[1].actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  /**
   * `parser.parse_args()`: like `parseKnownArgs` but any leftover argument is an
   * error.  On failure the process exits with status 2.
   */
  parseArgs(args = sysArgv.slice(1)) {
    try {
      const [namespace, extras] = this.parseKnownArgsOrThrow(args);
      if (extras.length > 0) {
        this.error(`unrecognized arguments: ${extras.join(' ')}`);
      }
      return namespace;
    } catch (error) {
      if (error instanceof SystemExit) exit(error.code);
      if (error instanceof ArgumentError) this.error(error.message);
      throw error;
    }
    // `error()` and `exit()` never return.
  }

  /** The parsing core; throws `ArgumentError`/`SystemExit` instead of exiting. */
  parseKnownArgsOrThrow(args) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.default !== undefined) namespace[action.dest] = action.default;
    }

    const extras = [];
    const seen = new Set();
    let separatorSeen = false;
    let index = 0;

    while (index < args.length) {
      const arg = args[index];

      if (separatorSeen) {
        extras.push(arg);
        index += 1;
        continue;
      }
      if (arg === '--') {
        // Everything after the first `--` is positional; the separator itself
        // stays behind as an extra because this parser has no positionals.
        separatorSeen = true;
        extras.push(arg);
        index += 1;
        continue;
      }

      const optionTuple = this.parseOptional(arg);
      if (optionTuple === null || optionTuple.action === null) {
        extras.push(arg);
        index += 1;
        continue;
      }

      const { action, optionString, explicitArg } = optionTuple;
      seen.add(action);

      if (action.argumentCount === 0) {
        if (explicitArg !== null) {
          throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
        }
        action.call(this, namespace, null, optionString);
        index += 1;
        continue;
      }

      let rawValue;
      if (explicitArg !== null) {
        rawValue = explicitArg;
        index += 1;
      } else {
        const next = args[index + 1];
        if (next === undefined || next === '--' || this.parseOptional(next) !== null) {
          throw new ArgumentError(action, 'expected one argument');
        }
        rawValue = next;
        index += 2;
      }

      action.call(this, namespace, this.getValue(action, rawValue), optionString);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /** `parse_known_args()`: leftovers are returned rather than rejected. */
  parseKnownArgs(args = sysArgv.slice(1)) {
    try {
      return this.parseKnownArgsOrThrow(args);
    } catch (error) {
      if (error instanceof SystemExit) exit(error.code);
      if (error instanceof ArgumentError) this.error(error.message);
      throw error;
    }
  }

  /**
   * argparse's `_parse_optional`: decide whether `argString` is an option and
   * which action it belongs to.
   *
   * @returns {null|{action: object|null, optionString: string, explicitArg: string|null}}
   *   `null` when the token is not option-like at all; an entry with
   *   `action === null` for an option-like token no action claims.
   */
  parseOptional(argString) {
    if (argString.length === 0) return null;
    if (!this.prefixChars.includes(argString[0])) return null;

    if (this.optionStringActions.has(argString)) {
      return {
        action: this.optionStringActions.get(argString),
        optionString: argString,
        explicitArg: null,
      };
    }
    if (argString.length === 1) return null;

    const equalsIndex = argString.indexOf('=');
    if (equalsIndex !== -1) {
      const optionString = argString.slice(0, equalsIndex);
      const explicitArg = argString.slice(equalsIndex + 1);
      if (this.optionStringActions.has(optionString)) {
        return { action: this.optionStringActions.get(optionString), optionString, explicitArg };
      }
    }

    const candidates = this.getOptionTuples(argString);
    if (candidates.length > 1) {
      const names = candidates.map((candidate) => candidate.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${names}`);
    }
    if (candidates.length === 1) return candidates[0];

    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  /** argparse's `_get_option_tuples`: unambiguous prefix abbreviation. */
  getOptionTuples(argString) {
    const result = [];
    const doubleDash = this.prefixChars.repeat(2);

    if (argString.startsWith(doubleDash)) {
      let prefix = argString;
      let explicitArg = null;
      const equalsIndex = argString.indexOf('=');
      if (equalsIndex !== -1) {
        prefix = argString.slice(0, equalsIndex);
        explicitArg = argString.slice(equalsIndex + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) {
          result.push({ action, optionString, explicitArg });
        }
      }
      return result;
    }

    // Single-dash form: `-xvalue` or `-x value`.
    const shortOptionPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortOptionPrefix) {
        result.push({ action, optionString, explicitArg: shortExplicitArg });
      } else if (optionString.startsWith(argString)) {
        result.push({ action, optionString, explicitArg: null });
      }
    }
    return result;
  }

  /** argparse's `_get_value`: run the `type` callable and wrap failures. */
  getValue(action, rawValue) {
    if (action.type === null) return rawValue;
    const typeName = action.type.typeName ?? action.type.name ?? 'value';
    try {
      return action.type(rawValue);
    } catch (error) {
      if (error instanceof ArgumentTypeError) {
        throw new ArgumentError(action, error.message);
      }
      throw new ArgumentError(action, `invalid ${typeName} value: ${pyRepr(rawValue)}`);
    }
  }

  /** `format_usage()`. */
  formatUsage() {
    return this.createFormatter().formatUsage(this.actions);
  }

  /** `format_help()`. */
  formatHelp() {
    return this.createFormatter().formatHelp(this.actions, this.groups);
  }

  printUsage(write = writeStdout) {
    write(this.formatUsage());
  }

  printHelp(write = writeStdout) {
    write(this.formatHelp());
  }

  /** `parser.error()`: usage plus message on stderr, then exit status 2. */
  error(message) {
    this.printUsage(writeStderr);
    writeStderr(`${this.prog}: error: ${message}\n`);
    exit(2);
  }

  createFormatter() {
    return new HelpFormatter(this.prog);
  }
}

/** argparse's dest inference: first long option, dashes turned into underscores. */
function destFromOptionStrings(optionStrings, prefixChars) {
  const isLong = (option) => option.length > 1 && prefixChars.includes(option[1]);
  const chosen = optionStrings.find(isLong) ?? optionStrings[0];
  return chosen.replace(/^[-]+/, '').replace(/-/g, '_');
}

