#!/usr/bin/env node
/** Randomised differential fuzzing of the argument vector and int literals. */
import { spawnSync } from 'node:child_process';

const PY = '/tmp/test3.mjs';
const JS = ['/output/test3.mjs'];

const SPACES = ['\t', '\n', '\v', '\f', '\r', ' ', '', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ', '　',
  '', '', '​', '﻿'];
const DIGITS = ['0', '9', '٥', '५', '๗', '５', '𝟽', '𝟶', '໙', '۴'];
const JUNK = ['', '_', '+', '-', '.', 'x', '0x', 'e5', '·', '〇', '１', ',', '٫'];
const TOKENS = ['--a', '--b', '--', '-', '-h', '--h', '--help', '--a=', '--b=',
  '-a', '--c', '--5', '-5', '-3.5', 'pos', '', '--a=1', '--b=v', '--ab'];

const rand = (array) => array[Math.floor(Math.random() * array.length)];

function randomIntish() {
  let out = '';
  const parts = 1 + Math.floor(Math.random() * 5);
  for (let i = 0; i < parts; i += 1) {
    const roll = Math.random();
    if (roll < 0.45) out += rand(DIGITS);
    else if (roll < 0.7) out += rand(JUNK);
    else out += rand(SPACES);
  }
  return out;
}

function randomArgv() {
  const length = Math.floor(Math.random() * 6);
  const argv = [];
  for (let i = 0; i < length; i += 1) {
    argv.push(Math.random() < 0.45 ? rand(TOKENS) : randomIntish());
  }
  return argv;
}

function run(cmd, args, argv) {
  const result = spawnSync(cmd, [...args, ...argv], { encoding: 'utf8' });
  return `${result.status}�${result.stdout}�${result.stderr}`;
}

