/**
 * Action objects — the descriptors argparse builds for every `add_argument()`
 * call.  Only the behaviours reachable from the source script are modelled:
 * `store` (the default) and `help`.
 */

import { SystemExit } from './errors.mjs';

/** Base class holding the shared option metadata. */
export class Action {
  constructor({
    optionStrings = [],
    dest = null,
    nargs = null,
    type = null,
    required = false,
    help = null,
    metavar = null,
    defaultValue = null,
  } = {}) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.type = type;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.default = defaultValue;
  }

  /** Number of command line arguments this action consumes (`nargs=None` → 1). */
  get argumentCount() {
    return this.nargs === null ? 1 : this.nargs;
  }

  // eslint-disable-next-line no-unused-vars
  call(parser, namespace, values, optionString) {
    throw new Error('Action.call must be overridden');
  }
}

/** `action='store'`: assign the converted value to `namespace[dest]`. */
export class StoreAction extends Action {
  call(parser, namespace, values) {
    namespace[this.dest] = values;
  }
}

/** `action='help'`: print the help text and terminate successfully. */
export class HelpAction extends Action {
  constructor(options) {
    super({ ...options, nargs: 0, defaultValue: undefined });
  }

  call(parser) {
    parser.printHelp();
    throw new SystemExit(0);
  }
}

